/** Packaging only: pad, remove imperceptible alpha speckles, downsample and encode.
 * Creative pixels are generated by the built-in image tool, never painted here.
 * NODE_PATH=/path/to/node_modules node scripts/prepare-cat-art-v2.cjs [source-directory]
 */
const fs = require('node:fs/promises');
const path = require('node:path');
const sharp = require('sharp');
const target = path.resolve(__dirname, '../public/assets/cats/art-v2');
const source = process.argv[2] || path.resolve(__dirname, '../docs/cat-art-v2/sources');
const ids = ['persian','exotic-shorthair','bengal','abyssinian'];
(async()=>{
  await fs.mkdir(target,{recursive:true});
  const manifest={version:2,generator:'built-in image_gen; model ID not exposed',portraits:[],backgrounds:[]};
  for(const id of ids){
    const file=path.join(source,`${id}-source.png`);
    const {data,info}=await sharp(file).ensureAlpha().raw().toBuffer({resolveWithObject:true});
    let cleared=0;
    for(let a=3;a<data.length;a+=4)if(data[a]>0&&data[a]<8){data[a]=0;cleared++;}
    const padded=await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).extend({top:16,bottom:16,left:16,right:16,background:{r:0,g:0,b:0,alpha:0}}).png().toBuffer();
    for(const size of [768,256])await sharp(padded).resize(size,size).webp({quality:size===768?91:87,alphaQuality:100,effort:6}).toFile(path.join(target,`${id}${size===256?'-thumb':''}.webp`));
    manifest.portraits.push({id,sourceSize:[info.width,info.height],padding:16,runtime:[768,768],thumbnail:[256,256],imperceptibleAlphaPixelsRemoved:cleared});
  }
  for(const season of ['spring','autumn','winter','night']){
    const file=path.join(source,`${season}-source.png`),meta=await sharp(file).metadata();
    await sharp(file).webp({quality:92,effort:6}).toFile(path.join(target,`courtyard-${season}.webp`));
    manifest.backgrounds.push({id:season,image:`assets/cats/art-v2/courtyard-${season}.webp`,width:meta.width,height:meta.height,nativeResolution:true,upscaled:false});
  }
  const files=(await fs.readdir(target)).filter(p=>p.endsWith('.webp'));
  manifest.totalRuntimeBytes=(await Promise.all(files.map(p=>fs.stat(path.join(target,p))))).reduce((n,s)=>n+s.size,0);
  await fs.writeFile(path.join(target,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
  console.log(JSON.stringify(manifest,null,2));
})();
